import React from "react";
import Myinfo from "./myInfoProfileComponent";
import Posts from "./postsComponenet";
import Otherinfo from "./otherInfoProfileComponent";

class Profile extends React.Component {
    constructor(props){
        super(props);
        this.state = {
            loading:true,
            user: null,
            posts: null,
            base_URL: ""
        };
    }

    componentDidMount() {
        let token = localStorage.getItem("token");

        if (!token) {
            window.location.href = "/login";
            return;
        }

        fetch("http://localhost:8000/api/profile", {
            headers: {
                "Accept": "application/json",
                "Authorization": "Bearer " + token
            }
        })
        .then(res => res.json())
        .then(json => {
            console.log(json.user);
            this.setState({
                user: json.user,
                posts: json.posts,
                base_URL: json.base_URL,
                loading:false
            });
            console.log('aa');
        })
        .catch(err => console.log("ERR:", err));
    }
    render() {
        
        return (
            <>
                <main className="container mt-4 pt-5">
                    <div className="container-fluid mt-5">
                        <div class="container p-4 item-back border rounded-5">
                            <Myinfo
                                name={this.state.user.name}
                                bio={this.state.user.bio}
                                profile={this.state.user.img}
                                base_URL={this.state.base_URL}
                            />
                            <div class="d-flex flex-wrap gap-4 mb-4">
                                <div class="text-center">
                                    <a href="highlight.php?id=1" class="text-decoration-none">
                                        <div class="ratio ratio-1x1" style={{width: "80px"}}>
                                            <img src="../img/s25.jpg" alt="Travel" class="rounded-circle border w-100 h-100 object-fit-cover"/>
                                        </div>
                                        <p class="small text-muted mt-2">Travel</p>
                                    </a>
                                </div>
                                <div class="text-center">
                                    <a href="highlight.php?id=2" class="text-decoration-none">
                                        <div class="ratio ratio-1x1" style={{width: "80px"}}>
                                            <img src="../img/s25.jpg" alt="Design" class="rounded-circle border w-100 h-100 object-fit-cover"/>
                                        </div>
                                        <p class="small text-muted mt-2">Design</p>
                                    </a>
                                </div>
                                <div class="text-center">
                                    <a href="highlight.php?id=3" class="text-decoration-none">
                                        <div class="ratio ratio-1x1" style={{width: "80px"}}>
                                            <img src="../img/s25.jpg" alt="Code" class="rounded-circle border w-100 h-100 object-fit-cover"/>
                                        </div>
                                        <p class="small text-muted mt-2">Code</p>
                                    </a>
                                </div>
                            </div>
                            <div class="row row-cols-1 row-cols-md-2 row-cols-xl-3 g-4">
                                <Posts/>
                                <Posts/>
                                <Posts/>
                                <Posts/>
                                <Posts/>
                                <Posts/>
                                <Posts/>
                                <Posts/>
                                <Posts/>
                                <Posts/>
                            </div>
                        </div>
                    </div>
                </main>
            </>
        );
     
    }
}
export default Profile;
